import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { SupplierService } from '../../services/supplier-service';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';

export interface Supplier {
  id: number;
  name: string;
  address: string;
  gstin: string;
  state: string;
  stateCode: number;
  phone?: string;
  email?: string;
}

@Component({
  selector: 'app-supplier',
  imports: [CommonModule, RouterLink, FormsModule],
  templateUrl: './supplier.html',
  styleUrl: './supplier.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SupplierComponent {
 supplier: Supplier[] = [];
searchTerm = '';

  constructor(private service: SupplierService, private cd: ChangeDetectorRef) {}

  ngOnInit() {
    this.service.getSuppliers().subscribe({
      next: (data) => {
        this.supplier = data;
         this.cd.markForCheck();
        console.log("Parties from backend:", this.supplier);
      },
      error: (err) => console.error("Error fetching parties:", err)
    });
  }

  filteredSupplier() {
    const term = this.searchTerm.toLowerCase();
    return this.supplier.filter(s =>
      s.name.toLowerCase().includes(term) ||
      s.address.toLowerCase().includes(term) ||
      s.gstin.toLowerCase().includes(term) ||
      s.state.toLowerCase().includes(term) ||
      s.stateCode.toPrecision().includes(term) ||
      s.phone?.toLowerCase().includes(term) ||
      s.email?.toLowerCase().includes(term)
    );
  }
}
